    "POST /partial_packing_slip/{fulfillment_id}": {
      "method": "POST",
      "path": "/partial_packing_slip/{fulfillment_id}",
      "risk": "R",
      "description": "Render Partial Packing Slip",
      "input_schema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "object",
            "properties": {
              "fulfillment_id": {
                "anyOf": [
                  {
                    "type": "integer",
                    "minimum": 1,
                    "maximum": 9007199254740991
                  },
                  {
                    "type": "string",
                    "pattern": "^-?(0|[1-9][0-9]{0,18})$",
                    "maxLength": 20
                  }
                ],
                "x-integer-format": "int64",
                "x-integer-minimum": "1",
                "description": "The unique identifier of the fulfillment to render a partial packing slip for. Must be a positive integer."
              }
            },
            "required": [
              "fulfillment_id"
            ],
            "additionalProperties": false
          },
          "body": {
            "$ref": "#/$defs/PartialPackingSlipRequest"
          }
        },
        "required": [
          "path",
          "body"
        ],
        "additionalProperties": false,
        "description": "Renders a partial packing slip for a fulfillment as an HTML document (which can be\nprinted or converted to PDF).\n\nNote: although the path parameter is named `fulfillment_id`, this value is the\npick-list-group ID used by the packing-slip flow.\n\nUnlike the full packing slip, a partial packing slip includes only the specified subset\nof sale line items and the exact quantities being packed. This is useful when a\nfulfillment is shipped across multiple parcels or in multiple stages.\n\nEach entry in `packed_line_items` must reference a valid sale line item and specify a\npositive quantity that does not exceed the quantity already packed on the pick lists.\n\nUse the optional `lang` field to control the language of the static template strings.\nWhen omitted or invalid, the packing slip defaults to `en-US`.\n\n🔒 Requires: `sales:read` scope",
        "$defs": {
          "PartialPackingSlipRequest": {
            "type": "object",
            "required": [
              "packed_line_items"
            ],
            "description": "Request body describing the subset of line items and quantities to render on a partial packing slip",
            "properties": {
              "lang": {
                "type": "string",
                "description": "BCP 47 language tag used to localize the static template strings on the packing slip. Defaults to `en-US` when omitted or unrecognized.",
                "maxLength": 262144
              },
              "packed_line_items": {
                "type": "array",
                "minItems": 1,
                "description": "The sale line items and quantities to include on the partial packing slip. Must contain at least one item.",
                "items": {
                  "$ref": "#/$defs/PackedLineItem"
                },
                "maxItems": 100
              }
            },
            "additionalProperties": false
          },
          "PackedLineItem": {
            "type": "object",
            "required": [
              "sale_line_item_id",
              "quantity"
            ],
            "description": "A single sale line item and the quantity to include on the partial packing slip",
            "properties": {
              "quantity": {
                "type": "number",
                "description": "The quantity of this line item to pack. Must be a positive finite number and must not exceed the quantity already packed on the pick lists."
              },
              "sale_line_item_id": {
                "type": "string",
                "description": "The ID of the sale line item to include on the packing slip",
                "maxLength": 262144,
                "format": "uuid"
              }
            },
            "additionalProperties": false
          }
        }
      },
      "wire": [
        {
          "name": "fulfillment_id",
          "in": "path",
          "style": "form",
          "explode": true
        }
      ],
      "defaults": {
        "query": {},
        "body": {}
      },
      "responses": {
        "200": {
          "media": "text/html",
          "schema": {
            "description": "The rendered partial packing slip as an HTML document.",
            "type": "string"
          }
        }
      }
    },
