    "AuditLogEvent": {
      "description": "The structure of the event and security event model",
      "properties": {
        "action": {
          "description": "The type of the action performed on the object.",
          "enum": [
            "insert",
            "update",
            "delete"
          ],
          "type": "string"
        },
        "created_at": {
          "description": "The timestamp indicating when the event was persisted to the audit log.",
          "format": "date-time",
          "type": "string"
        },
        "data": {
          "description": "An object in JSON format representing the new values of the attributes that were changed by the event.",
          "oneOf": [
            {
              "type": "object"
            },
            {
              "items": {
                "type": "object"
              },
              "type": "array"
            }
          ]
        },
        "entity_id": {
          "description": "The id of the object involved in the event",
          "maxLength": 36,
          "type": "string"
        },
        "id": {
          "description": "Autogenerated object identifier.",
          "type": "string"
        },
        "ip_address": {
          "description": "The ip address from which the request causing the event originated.",
          "format": "ipv4",
          "maxLength": 64,
          "type": "string"
        },
        "occurred_at": {
          "description": "The timestamp indicating when the action causing the event occurred.",
          "format": "date-time",
          "type": "string"
        },
        "old_data": {
          "description": "An object in JSON format representing the old values of the attributes that were changed by the event.",
          "type": "object"
        },
        "type": {
          "description": "The type of the object involved in the event. This may be something like \"security\" for security events or the name of the table the action was performed on, like \"vend_customer\".",
          "maxLength": 64,
          "type": "string"
        },
        "user_agent": {
          "description": "User agent of the http client which submitted the request.",
          "maxLength": 500,
          "type": "string"
        },
        "user_id": {
          "description": "The `id` of the user executing the action registered by this event.",
          "maxLength": 36,
          "type": "string"
        }
      },
      "title": "Audit Log Event",
      "type": "object",
      "x-examples": {
        "example-1": {
          "action": "insert",
          "created_at": "2019-08-24T14:15:22Z",
          "data": {},
          "entity_id": "string",
          "id": "string",
          "ip_address": "192.168.0.1",
          "occurred_at": "2019-08-24T14:15:22Z",
          "old_data": {},
          "type": "string",
          "user_agent": "string",
          "user_id": "string"
        }
      }
    },
