    "BasketRequest": {
      "properties": {
        "conditions": {
          "description": "Contextual conditions affecting pricing and promotions.\n",
          "items": {
            "oneOf": [
              {
                "type": "string"
              },
              {
                "items": {
                  "type": "object"
                },
                "type": "array"
              },
              {
                "type": "object"
              }
            ],
            "properties": {
              "type": {
                "description": "Condition type.",
                "enum": [
                  "channel",
                  "customer_group",
                  "customer_id",
                  "promo_code",
                  "outlet_id",
                  "tax_removal",
                  "sale_discount",
                  "price_overrides",
                  "line_item_discount_percentages",
                  "credit_redemption"
                ],
                "type": "string"
              },
              "value": {
                "description": "Value shape depends on `type`: - `channel`: string (channel ID) - `customer_group`: string (customer group ID) - `customer_id`: string (customer ID) - `promo_code`: string (promo code) - `outlet_id`: string (outlet ID) - `tax_removal`: array of TaxRemoval objects - `sale_discount`: SaleDiscountCondition object - `price_overrides`: array of PriceOverride objects - `line_item_discount_percentages`: array of LineItemDiscountPercentage objects - `credit_redemption`: array of CreditRedemption objects\n"
              }
            },
            "required": [
              "type",
              "value"
            ],
            "type": "object"
          },
          "minItems": 1,
          "type": "array"
        },
        "config": {
          "properties": {
            "advanced_promotion": {
              "default": false,
              "description": "Enable advanced promotion engine.",
              "type": "boolean"
            },
            "disable_promotions": {
              "default": false,
              "description": "Disable all promotion calculations.",
              "type": "boolean"
            },
            "resolve_tax": {
              "default": false,
              "description": "Resolve tax rates from the outlet configuration instead of requiring tax_rate on each product. Requires an outlet_id condition.\n",
              "type": "boolean"
            }
          },
          "type": "object"
        },
        "items": {
          "description": "Line items in the basket. At least one required.",
          "items": {
            "properties": {
              "id": {
                "description": "Unique line item ID within this basket.",
                "type": "string"
              },
              "product": {
                "properties": {
                  "id": {
                    "description": "Product ID.",
                    "type": "string"
                  },
                  "quantity": {
                    "description": "Quantity (decimal string). Must be positive.\n",
                    "example": "2.000",
                    "type": "string"
                  },
                  "tax_rate": {
                    "description": "Tax rate as a decimal (e.g. \"0.15\" for 15%). Required unless config.resolve_tax=true. Must be positive.\n",
                    "type": "string"
                  }
                },
                "required": [
                  "id",
                  "quantity"
                ],
                "type": "object"
              }
            },
            "required": [
              "id",
              "product"
            ],
            "type": "object"
          },
          "minItems": 1,
          "type": "array"
        },
        "request_id": {
          "description": "Optional client-supplied idempotency ID. Echoed back in the response.",
          "type": "string"
        },
        "sale_channel": {
          "description": "Sale channel. `Register` = in-store, `Ecommerce` = online. Null if not applicable.\n",
          "enum": [
            "Register",
            "Ecommerce"
          ],
          "nullable": true,
          "type": "string"
        }
      },
      "required": [
        "items",
        "conditions"
      ],
      "type": "object"
    },
